package com.giovannielena.restaurant.entity;
import jakarta.persistence.*; import lombok.*; import java.math.BigDecimal; import java.time.LocalDateTime; import java.util.*;
@Entity @Table(name="orders") @Getter @Setter @NoArgsConstructor @AllArgsConstructor
public class Order { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="order_id") private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="user_id") private User user; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="address_id") private Address address; @Column(name="total_amount",nullable=false,precision=10,scale=2) private BigDecimal totalAmount=BigDecimal.ZERO; @Enumerated(EnumType.STRING) @Column(nullable=false) private Status status=Status.PENDING; @Enumerated(EnumType.STRING) @Column(name="order_type",nullable=false) private OrderType orderType=OrderType.DELIVERY; @Column(name="special_instructions") private String specialInstructions; @Column(name="created_at",nullable=false) private LocalDateTime createdAt=LocalDateTime.now(); @OneToMany(mappedBy="order",cascade=CascadeType.ALL,orphanRemoval=true) private List<OrderItem> items=new ArrayList<>(); public enum Status{PENDING,CONFIRMED,PREPARING,READY,OUT_FOR_DELIVERY,DELIVERED,CANCELLED} public enum OrderType{DELIVERY,PICKUP} }